INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist "messbar" ein Kriterium des SMART-Prinzips?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der SMART-Definition"}, {"text": "Nein", "correct": false, "because": "Es gehört dazu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Merkmal beschreibt "messbar" im SMART-Prinzip?', 3, '[{"text": "Quantifizierbare Ergebnisse", "correct": true, "because": "Erlaubt Erfolgsmessung"}, {"text": "Vage Absichten", "correct": false, "because": "Widerspricht Messbarkeit"}, {"text": "Unklare Ziele", "correct": false, "because": "Nicht messbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Messbare Ziele haben Kriterien. b) Messbarkeit ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Messbarkeit ist zwingend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) trifft zu"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente machen ein Ziel messbar?', 4, '[{"text": "Zahlenangaben", "correct": true, "because": "Quantifizieren Ergebnisse"}, {"text": "Subjektive Meinungen", "correct": false, "because": "Nicht messbar"}, {"text": "Klar definierte Einheiten", "correct": true, "because": "Ermöglichen Vergleich"}, {"text": "Unklare Formulierungen", "correct": false, "because": "Widerspricht Messbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ziel ohne Messbarkeit SMART sein?', 2, '[{"text": "Nein", "correct": true, "because": "Messbarkeit ist Kernkriterium"}, {"text": "Ja", "correct": false, "because": "Widerspricht SMART"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel ist nicht messbar?', 3, '[{"text": "Team glücklicher machen", "correct": true, "because": "Subjektiv, nicht quantifizierbar"}, {"text": "50 Tickets bis Freitag lösen", "correct": false, "because": "Klar messbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Messbarkeit nur für quantitative Ziele wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch qualitative Ziele können messbar sein"}, {"text": "Ja", "correct": false, "because": "Messbarkeit ist breiter"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Ansatz hilft, Messbarkeit sicherzustellen?', 3, '[{"text": "KPI-Definition", "correct": true, "because": "Leistungskennzahlen messen Fortschritt"}, {"text": "Vage Beschreibungen", "correct": false, "because": "Verhindern Messung"}, {"text": "Keine Dokumentation", "correct": false, "because": "Erschwert Nachverfolgung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Messbarkeit erfordert klare Kriterien. b) Messbarkeit macht Ziele schwerer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, erleichtert Kontrolle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was fehlt bei "Server verbessern"?', 2, '[{"text": "Messbarkeit", "correct": true, "because": "Keine quantifizierbaren Kriterien"}, {"text": "Teamzuweisung", "correct": false, "because": "Nicht Teil von SMART"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein messbares Ziel qualitative Aspekte enthalten?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Skalen messbar"}, {"text": "Nein", "correct": false, "because": "Qualität kann quantifiziert werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel ist messbar?', 3, '[{"text": "10% weniger Fehler bis März", "correct": true, "because": "Klar quantifizierbar"}, {"text": "Software besser machen", "correct": false, "because": "Nicht spezifisch"}, {"text": "Team motivieren", "correct": false, "because": "Subjektiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist Messbarkeit immer objektiv?', 2, '[{"text": "Nein", "correct": true, "because": "Kann auch subjektive Skalen nutzen"}, {"text": "Ja", "correct": "false", "because": "Flexibilität ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien unterstützen die Messbarkeit?', 4, '[{"text": "Prozentsätze", "correct": true, "because": "Quantifizieren Fortschritt"}, {"text": "Allgemeine Aussagen", "correct": false, "because": "Nicht messbar"}, {"text": "Zeitangaben", "correct": true, "because": "Ermöglichen Vergleich"}, {"text": "Klar definierte Ziele", "correct": true, "because": "Machen Messung möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein messbares Ziel immer Zahlen enthalten?', 2, '[{"text": "Nein", "correct": true, "because": "Kann durch Kriterien messbar sein"}, {"text": "Ja", "correct": false, "because": "Flexibilität ist erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Messbarkeit im SMART-Prinzip?', 3, '[{"text": "Ermöglicht Fortschrittskontrolle", "correct": true, "because": "Überprüft Erfolg"}, {"text": "Verhindert Planung", "correct": false, "because": "Fördert Struktur"}, {"text": "Ignoriert Zeit", "correct": false, "because": "Hängt mit Terminen zusammen"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Ziel wie "bessere Kommunikation" messbar sein?', 2, '[{"text": "Ja", "correct": true, "because": "Mit Kriterien wie Antwortzeit"}, {"text": "Nein", "correct": false, "because": "Kann quantifiziert werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor macht "App fertigstellen" nicht messbar?', 3, '[{"text": "Fehlende Kriterien", "correct": true, "because": "Keine Erfolgsdefinition"}, {"text": "Teamgröße", "correct": false, "because": "Nicht relevant"}, {"text": "Budget", "correct": false, "because": "Anderer Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Messbarkeit hilft bei der Zielerreichung. b) Messbarkeit ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Messbarkeit ist zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Ziel der Messbarkeit im SMART-Prinzip?', 3, '[{"text": "Nachvollziehbarer Fortschritt", "correct": true, "because": "Ermöglicht Überprüfung"}, {"text": "Maximale Unklarheit", "correct": false, "because": "Widerspricht SMART"}, {"text": "Keine Struktur", "correct": false, "because": "Fördert Klarheit"}]');
